// CloudtainerML rev0023: predictive prefilling / chunk anchors toy for dLLM-like contexts.
// Synthetic C++17 probe: choose prefix chunks and optional periodic anchor tokens;
// measure lost-in-the-middle recall versus cost. Not a paper reproduction.
#include <algorithm>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <random>
#include <string>
#include <vector>
struct Chunk{double relevance,anchor,midpenalty; bool target;};
struct Row{std::string regime,method; int budget=0,n=0; double recall=0,cost=0,lost=0,utility=0;};
static std::string esc(const std::string&s){std::string o; for(char c:s){if(c=='"')o+="\\\""; else if(c=='\\')o+="\\\\"; else o+=c;} return o;}
static double rnd(std::mt19937_64&r,double a=0,double b=1){return std::uniform_real_distribution<double>(a,b)(r);} 
static std::vector<Chunk> make(std::mt19937_64&rng,const std::string&reg){int N=48; std::vector<Chunk> cs(N); for(int i=0;i<N;++i){double pos=std::abs((i+0.5)/N-0.5)*2; cs[i].relevance=rnd(rng); cs[i].anchor=0.15+rnd(rng)*0.3; cs[i].midpenalty=1.0-pos; cs[i].target=false;} int t=(reg=="lost_middle"?N/2:int(rng()%N)); if(reg=="adversarial_middle") t=N/2 + int(rng()%7)-3; if(reg=="query_sparse") t=int(rng()%N); for(int j=-1;j<=1;++j){int k=std::max(0,std::min(N-1,t+j)); cs[k].target=true; cs[k].relevance=0.75+rnd(rng)*0.25;} if(reg=="distractor_anchors") for(int i=0;i<N;i+=8){cs[i].anchor=0.9; cs[i].relevance=0.45+rnd(rng)*0.25;} return cs;}
static void eval(const std::string&reg,const std::string&m,int budget,int seed,double&rec,double&cost,double&lost,double&util){std::mt19937_64 rng(seed); auto cs=make(rng,reg); int N=cs.size(); std::vector<double> score(N); for(int i=0;i<N;++i){score[i]=cs[i].relevance; if(m.find("anchors")!=std::string::npos) score[i]+=0.28*cs[i].anchor; if(m=="middle_biased_dense") score[i]+=0.25*(1.0-cs[i].midpenalty); if(reg=="lost_middle" && m=="topk_chunks_no_anchors") score[i]-=0.42*cs[i].midpenalty; if(reg=="adversarial_middle" && m=="topk_chunks_no_anchors") score[i]-=0.55*cs[i].midpenalty; }
 std::vector<int> chosen; if(m=="dense_all_chunks"){for(int i=0;i<N;++i)chosen.push_back(i);} else if(m=="random_chunks"){for(int i=0;i<N;++i)chosen.push_back(i); std::shuffle(chosen.begin(),chosen.end(),rng); chosen.resize(std::min(budget,N));} else if(m=="oracle_chunks"){for(int i=0;i<N;++i) if(cs[i].target) chosen.push_back(i); for(int i=0;i<N && (int)chosen.size()<budget;++i) if(!cs[i].target) chosen.push_back(i);} else {std::vector<int> idx(N); for(int i=0;i<N;++i)idx[i]=i; std::sort(idx.begin(),idx.end(),[&](int a,int b){return score[a]>score[b];}); chosen.assign(idx.begin(),idx.begin()+std::min(budget,N));}
 std::vector<int> seen(N,0); for(int x:chosen)seen[x]=1; int targ=0,hit=0; double middle_miss=0; for(int i=0;i<N;++i)if(cs[i].target){targ++; hit+=seen[i]; if(!seen[i]) middle_miss+=cs[i].midpenalty;} rec=double(hit)/std::max(1,targ); cost=(m=="dense_all_chunks"?1.0:double(chosen.size())/N)+(m.find("anchors")!=std::string::npos?0.035:0.0); lost=middle_miss/std::max(1,targ); util=2.0*rec-0.55*cost-1.25*lost-(m=="oracle_chunks"?0.04:0.0);}
static void add(Row&r,double a,double b,double c,double d){r.n++;r.recall+=a;r.cost+=b;r.lost+=c;r.utility+=d;}
int main(int argc,char**argv){std::string out="artifacts/probe-results/REV0023_PREFILL_CHUNK_ANCHORS_SMOKE.json"; if(argc>1)out=argv[1]; auto t0=std::chrono::high_resolution_clock::now(); std::vector<std::string> regs={"lost_middle","adversarial_middle","query_sparse","distractor_anchors","benign"}; std::vector<std::string> ms={"dense_all_chunks","topk_chunks_no_anchors","topk_chunks_with_anchors","middle_biased_dense","random_chunks","oracle_chunks"}; std::vector<int> budgets={4,8,12,16}; std::map<std::string,Row> rows; std::map<std::string,int>wins,nonoracle; for(auto&reg:regs)for(int b:budgets)for(int seed=0;seed<120;++seed){double best=-1e9,bn=-1e9;std::string bw,bno;for(auto&m:ms){double r,c,l,u; eval(reg,m,b,seed*79+b*5+reg.size()*13,r,c,l,u); std::string key=reg+"|"+std::to_string(b)+"|"+m; if(!rows.count(key)){rows[key].regime=reg; rows[key].budget=b; rows[key].method=m;} add(rows[key],r,c,l,u); if(u>best){best=u;bw=m;} if(m.find("oracle")==std::string::npos&&u>bn){bn=u;bno=m;}} wins[bw]++; nonoracle[bno]++;}
 double sec=std::chrono::duration<double>(std::chrono::high_resolution_clock::now()-t0).count(); std::ofstream f(out); f<<std::fixed<<std::setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0023\",\n  \"probe\": \"prefill_chunk_anchors\",\n  \"language\": \"c++17\",\n  \"is_paper_reproduction\": false,\n  \"taxonomy\": [\"chunk-routing\", \"long-context\", \"cache\", \"lost-in-middle\"],\n"; f<<"  \"summary\": {\"row_count\": "<<rows.size()<<", \"seconds\": "<<sec<<", \"primary_metric\": {\"name\": \"mean_utility\", \"direction\": \"higher_is_better\", \"winner_field\": \"winner_counts_excluding_oracle\"}, \"tail_metrics\": {\"has_catastrophic_proxy\": true, \"fields\": [\"mean_lost_middle_miss\", \"mean_target_recall\"]}, \"winner_counts\": {"; bool first=true; for(auto&kv:wins){if(!first)f<<", "; first=false; f<<"\""<<esc(kv.first)<<"\": "<<kv.second;} f<<"}, \"winner_counts_excluding_oracle\": {"; first=true; for(auto&kv:nonoracle){if(!first)f<<", "; first=false; f<<"\""<<esc(kv.first)<<"\": "<<kv.second;} f<<"}, \"interpretation\": \"Chunk anchors are tested as periodic retrieval handles that can reduce lost-in-the-middle misses under sparse prefix selection.\"},\n  \"rows\": [\n"; int c=0; for(auto&kv:rows){auto&r=kv.second; double n=std::max(1,r.n); if(c++)f<<",\n"; f<<"    {\"regime\": \""<<esc(r.regime)<<"\", \"budget\": "<<r.budget<<", \"method\": \""<<esc(r.method)<<"\", \"mean_target_recall\": "<<r.recall/n<<", \"mean_cost\": "<<r.cost/n<<", \"mean_lost_middle_miss\": "<<r.lost/n<<", \"mean_utility\": "<<r.utility/n<<"}";} f<<"\n  ]\n}\n"; std::cerr<<"wrote "<<out<<" rows="<<rows.size()<<"\n"; return 0;}
